import csv,json,statistics
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
P=Path(__file__).resolve().parent
raw=list(csv.DictReader((P/'hnsw_raw.csv').open()));exact=list(csv.DictReader((P/'exact_raw.csv').open()));S=json.loads((P/'hnsw_summary.json').read_text());prov=json.loads((P/'provenance.json').read_text());queries=json.loads((P/'queries.json').read_text())
def avg(a):return statistics.mean(a)
cohorts=[]
for mode in ['all','walk_endpoint_text','independent_entity_text']:
 for h in [0,1,2,3,4]:
  for budget in [64,256,1024,4096]:
   rr=[r for r in raw if int(r['budget'])==budget and (h==0 or int(r['h'])==h) and (mode=='all' or r['mode']==mode)]
   if not rr:continue
   qids={int(r['qid']) for r in rr}
   bb=[r for r in exact if int(r['qid']) in qids and r['method']=='ForwardGF']
   cohorts.append(dict(mode=mode,h=h,budget=budget,queries=len(qids),mean_prefix_ms=avg(float(r['prefix_ms']) for r in rr),mean_recall=avg(float(r['recall']) for r in rr),underfill_rate=avg(int(r['underfill']) for r in rr),underfill_policy_ms=avg(float(r['prefix_ms'])+int(r['underfill'])*float(r['repair_ms']) for r in rr),underfill_policy_recall=avg(1 if int(r['underfill']) else float(r['recall']) for r in rr),forward_ms=avg(float(r['ms']) for r in bb),eligible_mean=avg(int(r['eligible']) for r in rr)))
with (P/'cohorts.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(cohorts[0]));w.writeheader();w.writerows(cohorts)
rng=np.random.default_rng(20261023);ci=[]
for s in S['budgets']:
 rr=[r for r in raw if int(r['budget'])==s['budget']]
 base=np.array([avg(float(r['ms']) for r in exact if int(r['qid'])==qi and r['method']=='ForwardGF') for qi in range(80)])
 policy=np.array([avg(float(r['prefix_ms'])+int(r['underfill'])*float(r['repair_ms']) for r in rr if int(r['qid'])==qi) for qi in range(80)])
 idx=rng.integers(0,80,size=(2000,80));ratios=policy[idx].mean(1)/base[idx].mean(1)
 ci.append(dict(budget=s['budget'],policy_over_forward=float(policy.mean()/base.mean()),paired_query_bootstrap_95ci=np.quantile(ratios,[.025,.975]).tolist(),policy_faster_queries=int((policy<base).sum())))
(P/'paired_confidence.json').write_text(json.dumps(ci,indent=2))
stratified=[]
for h in [1,2,3,4]:
 qids=list(range((h-1)*20,h*20))
 a=np.array([avg(float(r['prefix_ms'])+int(r['underfill'])*float(r['repair_ms']) for r in raw if int(r['qid'])==q and int(r['budget'])==64) for q in qids])
 b=np.array([avg(float(r['ms']) for r in exact if int(r['qid'])==q and r['method']=='ForwardGF') for q in qids])
 idx=rng.integers(0,20,(2000,20));ratio=a[idx].mean(1)/b[idx].mean(1)
 stratified.append(dict(h=h,policy_over_forward=float(a.mean()/b.mean()),paired_query_bootstrap95ci=np.quantile(ratio,[.025,.975]).tolist(),policy_faster_queries=int((a<b).sum())))
(P/'h64_stratified_confidence.json').write_text(json.dumps(stratified,indent=2))
plt.rcParams.update({'font.size':9,'axes.spines.top':False,'axes.spines.right':False,'pdf.fonttype':42,'ps.fonttype':42})
fig,axes=plt.subplots(1,3,figsize=(10.7,3.1),constrained_layout=True)
budgets=[s['budget'] for s in S['budgets']];colors=['#1f77b4','#ff7f0e','#2ca02c','#9467bd'];F=S['exact_baselines']['ForwardGF']['mean']
axes[0].plot([s['prefix_ms']['mean'] for s in S['budgets']],[s['mean_recall'] for s in S['budgets']],'-o',color=colors[0])
for s in S['budgets']:axes[0].annotate(str(s['budget']),(s['prefix_ms']['mean'],s['mean_recall']),xytext=(0,8),textcoords='offset points',ha='center',fontsize=8)
axes[0].set(xlabel='Mean prefix latency (ms)',ylabel='Mean recall@K',ylim=(0,1.02),title='(a) HNSW prefix quality')
actual=json.loads((P/'actual_policy_summary.json').read_text())
baseactual=actual['baselines']['ForwardTopKHeap']['mean']
axes[1].bar(range(4),[s['ms']['mean']/baseactual for s in actual['budgets']],color=colors)
axes[1].axhline(1,color='black',linestyle='--',linewidth=1,label='Matched heap baseline')
axes[1].set(xticks=range(4),xticklabels=budgets,xlabel='Retrieved candidates L',ylabel='Actual policy / ForwardTopKHeap',title='(b) Actual stopping policy')
axes[1].legend(frameon=False,fontsize=8)
for s,c in zip(S['budgets'],colors):
 ps=np.linspace(0,1,11);axes[2].plot(ps,(s['prefix_ms']['mean']+ps*s['repair_ms']['mean'])/F,label=f"L={s['budget']}",color=c)
axes[2].axhline(1,color='black',linestyle='--',linewidth=1)
axes[2].set(xlabel='Independent fallback probability p',ylabel='Component expectation / ForwardSort',title='(c) Component-run expectation')
axes[2].legend(frameon=False,fontsize=8,ncol=2)
for a in axes:a.grid(axis='y',alpha=.2)
fig.savefig(P/'real_hnsw.pdf');fig.savefig(P/'real_hnsw.png',dpi=170)
lines=['# Real graph and standard HNSW revision experiment','','This cohort uses actual FB15k-237 training triples and entity descriptions. It is a new retrieval workload constructed on a public knowledge graph, not an externally established graph-filtered ANN benchmark.','',f"Graph: {prov['vertices']:,} entities; {prov['original_edges']:,} training edges and their explicitly labeled inverses ({prov['edges_with_inverses']:,} directed arcs, {prov['relations_with_inverses']} labels). No development/test triples enter the graph. {prov['description_coverage']:,} entities have descriptions; {prov['name_only_fallback']} use names. TF-IDF (min_df=2, max_features=50000, sublinear TF) produces {prov['tfidf_features']:,} features, then a seeded 128-component SVD and L2 normalization produce genuine corpus-derived vectors. These are lexical latent-semantic embeddings, not BERT or random vectors. Two entities produce zero vectors and remain in the universe, with identifier ties resolved deterministically.",'',f"Graph preprocessing {prov['graph_preprocessing_seconds']:.3f} s, TF-IDF fit {prov['tfidf_fit_seconds']:.3f} s, SVD fit {prov['svd_fit_seconds']:.3f} s; SVD explained variance {prov['svd_explained_variance']:.4f}. These times were measured on the Windows machine.",'','Queries: 80, uniformly sampled anchors and random outgoing walks, 20 per length h=1,2,3,4. Every second query uses the sampled endpoint description; the others use an independently sampled entity description. All use k=10. K=min(k,|C|), and recall is intersection/K. No query has empty truth. Cardinality min/median/max = 1/43/3717; anchor degree min/median/max = 1/26/538. Random walks favor relations represented by more outgoing arcs, and long walks can revisit entities. This is deliberately an exploratory cohort, not a production query distribution.','','Timing: Intel Core i9-12900K (16 physical / 24 logical cores), 34,088,476,672 bytes RAM, Windows 10, Python 3.11.14, hnswlib 0.8.0. Process pinned to logical CPU 4; HNSW and BLAS use one thread; GC disabled within the timing loop. One full workload warmup and three measured repetitions, with randomized query, method and budget order. HNSW runs are separate from the Linux server C++ cohort; cross-machine absolute times must not be pooled.','',f"HNSW: M=16, ef_construction=200, random_seed=20261023, ef=max(64,L), L in {{64,256,1024,4096}}. Index build {S['index_build_seconds']:.3f} s; file {S['index_file_bytes']:,} bytes; RSS increase {S['rss_after_index']-S['rss_before_index']:,} bytes (process delta, not an allocator-precise estimate). Standard HNSW queries are float32; candidate ranking and exact results use float64 dot(delta,delta) with ID ties.",'','The public HNSW API is called once per prefix budget. It does not retain a traversal frontier across budgets. Candidate eligibility is verified by memoized reverse recursion. Forward repair independently expands the graph and reuses explicitly computed prefix distances. This demonstrates a standard-index integration and approximate stopping rule; it does not validate an HNSW frontier-resume implementation.','','| L | Prefix mean ms | Prefix recall | Underfill rate | Policy mean ms | Policy recall | Independent p break-even vs ForwardGF |','|---:|---:|---:|---:|---:|---:|---:|']
for s in S['budgets']:lines.append(f"|{s['budget']}|{s['prefix_ms']['mean']:.6f}|{s['mean_recall']:.6f}|{s['underfill_rate']:.4f}|{s['underfill_policy_ms']:.6f}|{s['underfill_policy_recall']:.6f}|{s['forward_break_even_probability']:.6f}|")
lines+=['',f"Matched exact ForwardGF mean = {F:.6f} ms; plain recursive ColdMemo mean = {S['exact_baselines']['ColdMemo']['mean']:.6f} ms. ColdMemo is not the resumable ColdSuffix control. Median/IQR/p95 and per-query records are retained in the JSON/CSV files.",'','The underfill policy accepts a prefix only when it contains at least k legal objects; otherwise it executes exact forward repair. Thus it genuinely permits requests to stop early. The policy mean is mean(A_i + I_i B_i), with measured prefix A_i and actual incremental repair B_i, and I_i the underfill indicator. At L=4096, accepted queries 65 and 73 each have recall 0.9; aggregate policy recall is 0.9975. This is a direct counterexample to treating count sufficiency as a recall certificate.','','The independent-fallback sweep evaluates p=0,0.1,...,1 using E[T]=mean(A)+p mean(B) and E[R]=mean(r)+p(1-mean(r)). All A and B are measured, but these are analytical expectations for an independent Bernoulli choice, not a separately executed learned controller. p*=(mean(ForwardGF)-mean(A))/mean(B); negative p* means no feasible break-even interval. Underfill decisions are correlated with repair cost, so their observed rate cannot simply be substituted into this independent-p formula.','','Results are a boundary result: an inexpensive prefix can save time only at low independently imposed repair probabilities and low achieved recall; the measured underfill rule is slower than the matched strongest exact baseline. All prefixes produce legal objects; all 960 executed repairs and 480 exact baseline runs match independent edge-table truth. Paired bootstrap intervals resample the 80 queries, not the 240 repetitions, and are available in paired_confidence.json.','','Sources:','','- https://www.microsoft.com/en-us/download/details.aspx?id=52312 (original FB15K-237 dataset description)','- https://github.com/yao8839836/kg-bert/tree/f3f260309c5e2986467a66e0e68fa7f53b1a150e/data/FB15k-237 (actual downloaded triples/text; the upstream README identifies entity2textlong as entity textual sequences)','- https://github.com/nmslib/hnswlib/tree/v0.8.0 (standard ANN implementation)','','Reproduce in this folder (Python dependencies: numpy, scipy, scikit-learn, threadpoolctl, hnswlib==0.8.0, psutil, matplotlib):','','```text','python download_data.py','python prepare_real.py','python benchmark_hnsw.py','python audit_real.py','python analyze_real.py','```','','The timing script pins to CPU 4, which must exist. Dataset and result hashes are in provenance.json and hnsw_summary.json. Run-specific output hashes may differ after a rerun because timings and compressed file metadata change. The deterministic graph.bin and queries.txt hashes are stronger workload identity anchors.']
lines+=['','Stratified observations: at L=64, the h=4 cohort has policy mean 1.030453 ms versus ForwardGF 1.481313 ms (1.44x point-estimate speedup), but the paired query bootstrap interval for their ratio includes one. Only 7 of its 20 queries are faster, so this is suggestive and does not establish a reliable crossover. In the full 80-query cohort, the L=64 policy/ForwardGF ratio is 1.1751 with a 95% paired-query bootstrap interval [0.8520, 1.7249]. Corpus-derived alignment matters: endpoint-conditioned queries have L=64 prefix recall 0.7866, whereas independent entity texts have recall 0.1100. Endpoint conditioning deliberately enriches alignment and should not be treated as a natural query distribution.']
body='\n'.join(lines).replace('Policy mean ms','Reconstructed policy mean ms').replace('Thus it genuinely permits requests to stop early.','This stopping rule is evaluated by component reconstruction in this initial run; actual early-return timings are reported separately in ACTUAL_POLICY_REPORT.md.')
body=body.replace('The policy mean is mean(A_i + I_i B_i)','The reconstructed policy mean is mean(A_i + I_i B_i)')
body='> Timing clarification: the policy costs below are reconstructed from measured components; the initial benchmark executed repair for every prefix. Use ACTUAL_POLICY_REPORT.md for actual early-return timings and its matched stronger heap baseline. In real_hnsw.pdf, panel (b) uses the new actual-policy cohort and its 0.557107 ms heap baseline; panels (a) and (c) use the original component cohort and panel (c) uses its 0.658752 ms sort baseline. The timing cohorts are not pooled.\n\n'+body
(P/'REAL_EXPERIMENT_REPORT.md').write_text(body+'\n',encoding='utf8')
print('Created cohort table, confidence intervals, figure and report.');print(json.dumps(S['exact_baselines']));print(json.dumps(S['budgets']))
